// Offline guidance from the bundled vet advice pack. MUST stay behaviourally identical to the server's fallback
// (src/livestock_llm/advice.py): mobile/tests/guidance.test.ts checks it against output generated by the Python code.
import type { AdvicePack, AdviceEntry, ApiDetection, Report } from './types.ts';

const RANK = { none: 0, soon: 1, urgent: 2, emergency: 3 } as const;
const SEVERITY = { none: 'low', soon: 'moderate', urgent: 'high', emergency: 'urgent' } as const;
const FOLLOW_UP = { none: null, soon: 7, urgent: 2, emergency: 1 } as const;
type Urgency = keyof typeof RANK;

const dedupe = (items: string[], cap: number) => [...new Set(items)].slice(0, cap);

export function lookup(pack: AdvicePack, cls: string): AdviceEntry | undefined {
  const k = cls.toLowerCase();
  return pack.diseases.find((e) => e.label.toLowerCase() === k || e.aliases.some((a) => a.toLowerCase() === k));
}

/** Advice entries for the classes present, most confident first, without duplicates. */
export function forDetections(pack: AdvicePack, dets: { class: string; confidence: number }[]): AdviceEntry[] {
  const out: AdviceEntry[] = [];
  for (const d of [...dets].sort((a, b) => b.confidence - a.confidence)) {
    const e = lookup(pack, d.class);
    if (e && !out.some((x) => x.label === e.label)) out.push(e);
  }
  return out;
}

/** Screening flags the way the Vision API derives them (notifiable / zoonotic suspects), from the pack. */
export function flagsFor(pack: AdvicePack, dets: { class: string }[]): string[] {
  const entries = dets.map((d) => lookup(pack, d.class)).filter((e): e is AdviceEntry => !!e);
  const f: string[] = [];
  if (entries.some((e) => e.notifiable)) f.push('possible_notifiable_disease');
  if (entries.some((e) => e.zoonotic)) f.push('possible_zoonotic_risk');
  return f;
}

export function offlineGuidance(pack: AdvicePack, dets: ApiDetection[], flags: string[] = flagsFor(pack, dets)): Report {
  const entries = forDetections(pack, dets);
  const findings = entries.filter((e) => e.label !== 'healthy');
  const used = findings.length ? findings : entries.slice(0, 1);
  const counts = new Map<string, number>();
  for (const d of dets) counts.set(d.class, (counts.get(d.class) ?? 0) + 1);
  const top = used.reduce((m, e) => Math.max(m, RANK[e.urgency]), 0);
  const urgency = (Object.keys(RANK) as Urgency[]).find((k) => RANK[k] === top) as Urgency;
  const summary = (counts.size ? 'Findings: ' + [...counts].map(([c, n]) => `${n} x ${c.replace(/_/g, ' ')}`).join(', ') + '. ' : 'No finding was detected in this photo. ')
    + 'Preliminary result from the on-device model, with standard guidance from the veterinary advice pack.';
  return {
    summary,
    possible_conditions: findings.length ? findings.map((e) => e.title) : ['No condition recognised in this photo'],
    severity: SEVERITY[urgency],
    notifiable: used.some((e) => e.notifiable) || flags.includes('possible_notifiable_disease'),
    zoonotic: used.some((e) => !!e.zoonotic) || flags.includes('possible_zoonotic_risk'),
    immediate_actions: dedupe(used.flatMap((e) => e.do_now), 10),
    treatment: { supportive_care: dedupe(used.map((e) => e.see_vet), 6), medicines: [], requires_vet: true, withdrawal_periods: [] },
    prevention: dedupe(used.flatMap((e) => e.prevention), 8),
    follow_up_days: FOLLOW_UP[urgency],
    disclaimer: pack.disclaimer,
  };
}
